const results = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && rg --files -g 'AGENTS.md' -g '*SKILL*' -g '*infection*' -g 'composer.json' -g '*template*' -g '!vendor'",max_output_tokens:6000}),
  tools.exec_command({cmd:"git status --short && git branch --show-current",max_output_tokens:2000}),
  tools.exec_command({cmd:"cat /Users/ab/.agents/skills/find-docs/SKILL.md && cat /Users/ab/.codex/skills/.system/skill-creator/SKILL.md",max_output_tokens:10000}),
  tools.web__run({open:[{ref_id:"https://github.com/k-kinzal/ztd-query-php/blob/9e8a76156552c50dce52297b338fa1513815266f/packages/sql-faker/infection.json5"}],response_length:"long"})
]);
results.forEach((r,i)=>text({i,result:r}));
text(ALL_TOOLS.filter(x=>/search|docs/.test(x.name+" "+x.description)).map(x=>({name:x.name,description:x.description.slice(0,200)})).slice(0,50));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"cat AGENTS.md && cat skills/setup-toolkit-infection/SKILL.md && cat skills/setup-toolkit-infection/infection.json5",max_output_tokens:9000}),
  tools.exec_command({cmd:"rg --files skills && rg -n 'comment|コメント|rationale|reason|explain|document|# |//|<!--|/\\*' skills -g '!AGENTS.md'",max_output_tokens:12000}),
  tools.exec_command({cmd:"cat composer.json && rg --files .github tests | head -80 && rg -n 'skills/|SKILL.md|infection.json5' tests .github README.md docs -g '!*.snap'",max_output_tokens:8000}),
  tools.exec_command({cmd:"curl -fsSL 'https://raw.githubusercontent.com/k-kinzal/ztd-query-php/9e8a76156552c50dce52297b338fa1513815266f/packages/sql-faker/infection.json5'",max_output_tokens:6000})
]);results.forEach((r,i)=>text({i,result:r}));

